mapper.select:
SELECT conversation.id AS conversation_id, expires_at,
    (SELECT  FROM agent_conversation_visible_turn
     WHERE conversation_id=conversation.id ORDER BY turn_no LIMIT 1) AS title
FROM agent_conversation AS conversation
WHERE user_id=#{userId} AND expires_at > #{now}
ORDER BY expires_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM agent_conversation_visible_turn
WHERE conversation_id=#{id} AND turn_no <= (
    SELECT turn_no FROM (
        SELECT turn_no FROM agent_conversation_visible_turn WHERE conversation_id=#{id}
        ORDER BY turn_no DESC LIMIT 50, 1
    ) AS cutoff
)
